export async function POST(req: Request) {
  const { orderID } = await req.json();
  const response = await fetch(`https://api-m.sandbox.paypal.com/v2/checkout/orders/${orderID}/capture`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${process.env.PAYPAL_ACCESS_TOKEN}` }
  });
  const data = await response.json();
  const captureStatus = data?.purchase_units?.[0]?.payments?.captures?.[0]?.status;
  if (captureStatus === 'COMPLETED') {
    return NextResponse.json({ status: 'SUCCESS' });
  }
  return NextResponse.json({ status: 'FAILED' }, { status: 422 });
}

